cd /private/tmp/claude-501/-Volumes-Transcend-control-room/32fe60a1-e041-40fe-8193-6f7f1a82a633/scratchpad && grep unparseable capture.jsonl | head -3; cat > analyse.py <<'EOF'
import json, collections, statistics as st
rows=[json.loads(l) for l in open('capture.jsonl')]
kinds=collections.Counter(r['kind'] if r['kind']!='msg' else r['m'].get('type') for r in rows)
print('COUNTS', dict(kinds))
for r in rows:
    if r['kind'] not in ('msg',): print('EVENT', r)
route=None; seg_zone={}; seg_len={}
hb=[]; tel=collections.defaultdict(list); other=[]
for r in rows:
    if r['kind']!='msg': continue
    m=r['m']; t=m.get('type')
    if t=='hello':
        route=m['route']; seg_zone={s['segment_id']:s['zone_id'] for s in route}; seg_len={s['segment_id']:s['length_m'] for s in route}
        print('HELLO zones', [(z['zone_id'],z['status']) for z in m['zones'] if z['status']!='OPEN'], 'leases', m['leases'])
    elif t=='heartbeat': hb.append((r['rx_ms'], m['server_time_ms']))
    elif t=='telemetry': tel[m.get('vehicle_id')].append((r['rx_ms'], m))
    else: other.append(m)
if hb:
    d=[b[1]-a[1] for a,b in zip(hb,hb[1:])]; off=[rx-s for rx,s in hb]
    print('HEARTBEAT n=%d interval min/med/max %s/%s/%s  rx-server offset min/med/max %s/%s/%s'%(len(hb),min(d or[0]),st.median(d or[0]),max(d or[0]),min(off),st.median(off),max(off)))
EXPECTED={'type','vehicle_id','seq','t_device_ms','state','task','soc_pct','speed_mps','direction','segment_id','zone_id','offset_m','payload_kg','faults','control'}
STATES={'TRAMMING','LOADING','DUMPING','CHARGING','HOLDING','IDLE','MANUAL','ESTOPPED','FAULT'}
anom=collections.Counter(); examples=collections.defaultdict(list)
def flag(k, v, m):
    anom[(v,k)]+=1
    if len(examples[k])<3: examples[k].append((v, {x:m.get(x) for x in ('seq','state','segment_id','zone_id','offset_m','soc_pct','speed_mps','t_device_ms','faults','task','payload_kg')}))
for v in sorted(tel, key=str):
    seqs=[m.get('seq') for _,m in tel[v]]
    rx=[r for r,_ in tel[v]]; span=(rx[-1]-rx[0])/1000 if len(rx)>1 else 0
    dup=len(seqs)-len(set(seqs)); back=sum(1 for a,b in zip(seqs,seqs[1:]) if isinstance(a,int) and isinstance(b,int) and b<a)
    ints=sorted(s for s in set(seqs) if isinstance(s,int))
    gaps=sum(b-a-1 for a,b in zip(ints,ints[1:]) if b-a>1)
    skews=[m['t_device_ms']-r for r,m in tel[v] if isinstance(m.get('t_device_ms'),(int,float))]
    states=collections.Counter(m.get('state') for _,m in tel[v])
    socs=[m['soc_pct'] for _,m in tel[v] if isinstance(m.get('soc_pct'),(int,float))]
    print('%s n=%d rate=%.1fHz dups=%d backwards=%d missing=%d skew(dev-rx) med=%.0fms range=%.0f soc %.1f->%.1f states=%s'%(
        v,len(seqs),len(seqs)/span if span else 0,dup,back,gaps,st.median(skews) if skews else float('nan'),(max(skews)-min(skews)) if skews else 0,
        socs[0] if socs else -1, socs[-1] if socs else -1, dict(states)))
    prev=None
    for r,m in tel[v]:
        miss=EXPECTED-set(m); extra=set(m)-EXPECTED
        if miss: flag('missing:'+','.join(sorted(miss)),v,m)
        if extra: flag('extra:'+','.join(sorted(extra)),v,m)
        if m.get('state') not in STATES: flag('bad_state',v,m)
        sid=m.get('segment_id')
        if sid not in seg_zone: flag('unknown_segment',v,m)
        elif m.get('zone_id')!=seg_zone[sid]: flag('zone_segment_mismatch',v,m)
        off=m.get('offset_m')
        if isinstance(off,(int,float)) and sid in seg_len and not (0<=off<=seg_len[sid]): flag('offset_out_of_segment',v,m)
        s=m.get('soc_pct')
        if not isinstance(s,(int,float)) or not 0<=s<=100: flag('soc_out_of_range',v,m)
        sp=m.get('speed_mps')
        if not isinstance(sp,(int,float)) or sp<0 or sp>4.5: flag('speed_out_of_range',v,m)
        if m.get('state') in ('HOLDING','IDLE','LOADING','DUMPING','CHARGING','ESTOPPED','FAULT') and isinstance(sp,(int,float)) and sp>0.05: flag('moving_while_'+str(m.get('state')),v,m)
        if m.get('faults'): flag('faults:'+json.dumps(m['faults']),v,m)
        if prev and isinstance(m.get('seq'),int) and isinstance(prev.get('seq'),int) and m['seq']>prev['seq'] and isinstance(prev.get('soc_pct'),(int,float)) and isinstance(s,(int,float)) and abs(s-prev['soc_pct'])>3: flag('soc_jump',v,m)
        if prev and m.get('seq')!=prev.get('seq') and prev.get('segment_id') in seg_len and sid in seg_len:
            p0=[x['start_m'] for x in route if x['segment_id']==prev['segment_id']][0]+prev['offset_m']
            p1=[x['start_m'] for x in route if x['segment_id']==sid][0]+off
            d=(p1-p0)%1600; d=min(d,1600-d)
            dt=(r-prevrx)/1000
            if d>10 and d>6*max(dt,0.2): flag('position_jump',v,m)
        prev=m; prevrx=r
print('ANOMALIES')
for (v,k),n in sorted(anom.items(), key=lambda x:(x[0][1],x[0][0])): print('  ',k,v,n)
for k,ex in examples.items(): print('EX',k,ex[:2])
print('OTHER MESSAGES', len(other))
for m in other: print('  ', json.dumps(m)[:400])
EOF
python3 analyse.py 2>&1 | tail -60

