# Who is inside each non-OPEN zone, by latest telemetry per truck, with server-time ages.
import json
rows=[json.loads(l) for l in open('capture.jsonl')]
zones={}; latest={}; srv=None; srv_rx=None
for r in rows:
    if r['kind']!='msg': continue
    m=r['m']
    if 'server_time_ms' in m: srv, srv_rx = m['server_time_ms'], r['rx_ms']
    if m['type']=='hello': zones={z['zone_id']:z for z in m['zones']}
    if m['type']=='zone_event': zones[m['zone_id']]=m; print('ZONE', m['zone_id'], m['status'], m.get('reason'), 'eff in %.0fs'%(((m.get('effective_at_ms') or m['server_time_ms'])-m['server_time_ms'])/1000))
    if m['type']=='telemetry':
        v=m['vehicle_id']
        if v not in latest or (isinstance(m['seq'],int) and m['seq']>latest[v][1]['seq']): latest[v]=(r['rx_ms'],m)
now=rows[-1]['rx_ms']
for z,zz in zones.items():
    if zz['status']!='OPEN':
        inside=[(v,m['state'],m['segment_id'],m['offset_m'],'%.1fs'%((now-rx)/1000)) for v,(rx,m) in sorted(latest.items()) if m['zone_id']==z]
        print(z, zz['status'], 'until/at', zz.get('effective_at_ms'), 'server now~', srv+(now-srv_rx), 'inside:', inside)
EOF
