import json,collections
rows=[json.loads(l) for l in open('capture.jsonl')]
route=[r['m'] for r in rows if r['kind']=='msg' and r['m']['type']=='hello'][0]['route']
start={s['segment_id']:s['start_m'] for s in route}; zone_of={s['segment_id']:s['zone_id'] for s in route}
def f(x):
    try: return float(x)
    except: return None
def pos(m):
    o=f(m.get('offset_m')); return start[m['segment_id']]+o if o is not None and m.get('segment_id') in start else None
# server clock estimate from heartbeats: server ~= rx + offset (offset ~ -29ms); use rx directly
tel=collections.defaultdict(list)
for r in rows:
    if r['kind']=='msg' and r['m']['type']=='telemetry': tel[r['m']['vehicle_id']].append((r['rx_ms'],r['m']))
CL0,CL1=1790903033155,1790903134788
print('== trucks reporting DECLINE while CLOSED (by rx time) ==')
for v,l in sorted(tel.items()):
    inside=[(rx,m) for rx,m in l if CL0<=rx<=CL1 and m.get('zone_id')=='DECLINE']
    if inside: print(v,len(inside),'msgs; states',dict(collections.Counter(m['state'] for _,m in inside)),'first pos %.0f last pos %.0f'%(pos(inside[0][1]),pos(inside[-1][1])))
print('== HT-10 dup analysis ==')
by=collections.defaultdict(list)
for rx,m in tel['HT-10']: by[m['seq']].append((rx,m))
multi={s:x for s,x in by.items() if len(x)>1}
same=sum(1 for x in multi.values() if all(json.dumps(a[1],sort_keys=True)==json.dumps(x[0][1],sort_keys=True) for a in x))
print('seqs with >1 copy',len(multi),'identical-content',same)
big=sorted(multi.items(), key=lambda kv:-len(kv[1]))[:3]
for s,x in big: print(' seq',s,'copies',len(x),'rx span ms',x[-1][0]-x[0][0], 'pos',[round(pos(m) or -1,1) for _,m in x[:4]],'state',x[0][1]['state'],'speed',x[0][1]['speed_mps'])
# find the run of repeats in time
runs=[]; prev=None
for rx,m in tel['HT-10']:
    if prev and m['seq']==prev[1]['seq']: runs.append(rx)
    prev=(rx,m)
if runs: print(' repeat rx window %.0fs..%.0fs after start'%((runs[0]-rows[0]['rx_ms'])/1000,(runs[-1]-rows[0]['rx_ms'])/1000))
print('== HT-07 fault timeline ==')
ps=None
for rx,m in tel['HT-07']:
    k=(m['state'],tuple(m['faults']),m['task'])
    if k!=ps: print(' %+6.1fs seq %s %s %s faults=%s speed=%s pos=%.0f zone=%s ctrl=%s'%((rx-rows[0]['rx_ms'])/1000,m['seq'],m['state'],m['task'],m['faults'],m['speed_mps'],pos(m),m['zone_id'],m['control']['mode'])); ps=k
print('== HT-06 battery ==')
l=[(rx,m) for rx,m in tel['HT-06'] if f(m['soc_pct']) is not None]
for i in range(0,len(l),300): rx,m=l[i]; print(' %+6.1fs soc %.1f pos %.0f %s payload %s'%((rx-rows[0]['rx_ms'])/1000,f(m['soc_pct']),pos(m),m['state'],m['payload_kg']))
rx,m=l[-1]; print(' %+6.1fs soc %.1f pos %.0f %s (last)'%((rx-rows[0]['rx_ms'])/1000,f(m['soc_pct']),pos(m),m['state']))
print('== HT-03 silences >2s ==')
l=tel['HT-03']
for (a,ma),(b,mb) in zip(l,l[1:]):
    if b-a>2000: print(' %+6.1fs gap %.1fs seq %s->%s state %s->%s pos %.0f->%.0f'%((a-rows[0]['rx_ms'])/1000,(b-a)/1000,ma['seq'],mb['seq'],ma['state'],mb['state'],pos(ma),pos(mb)))
print('== speed vs displacement (median over 5s windows, TRAMMING) ==')
for v,l in sorted(tel.items()):
    ok=[(rx,m) for rx,m in l if pos(m) is not None and m['state']=='TRAMMING' and isinstance(m.get('speed_mps'),(int,float))]
    ok.sort(key=lambda x:x[1]['seq'])
    rat=[]
    for i in range(0,len(ok)-25,25):
        a,b=ok[i],ok[i+25]; d=(pos(b[1])-pos(a[1]))%1600; dt=(b[0]-a[0])/1000
        if dt>0 and b[1]['state']=='TRAMMING': rat.append(d/dt)
    rat.sort()
    if rat: print(' %s observed m/s med %.2f min %.2f max %.2f (reported %s)'%(v,rat[len(rat)//2],rat[0],rat[-1],collections.Counter(m['speed_mps'] for _,m in ok).most_common(2)))
print('== min spacing between trucks (same instant, latest per truck, sampled each 1s) ==')
evs=sorted((rx,m) for v in tel for rx,m in tel[v]); latest={}; mins=collections.Counter(); t0=evs[0][0]; nxt=t0
for rx,m in evs:
    if isinstance(m['seq'],int) and (m['vehicle_id'] not in latest or m['seq']>latest[m['vehicle_id']]['seq']): latest[m['vehicle_id']]=m
    if rx>=nxt:
        nxt+=1000; P=sorted((pos(x),k) for k,x in latest.items() if pos(x) is not None)
        for (p1,k1),(p2,k2) in zip(P,P[1:]):
            if p2-p1<5: mins[(k1,k2)]+=1
print(' pairs within 5 m (seconds observed):',dict(mins.most_common(6)))
EOF

