import json, collections
rows=[json.loads(l) for l in open('probe1.jsonl')]; T0=rows[0]['rx_ms']
def t(x): return '%+6.1fs'%((x-T0)/1000)
route=[r['m'] for r in rows if r['kind']=='msg' and r['m']['type']=='hello'][0]['route']; start={s['segment_id']:s['start_m'] for s in route}
def pos(m):
    try: return start[m['segment_id']]+float(m['offset_m'])
    except: return None
print('== link / zones / leases ==')
for r in rows:
    if r['kind'] in ('connected','closed_by_peer','error','replayed'): print(t(r['rx_ms']), r['kind'], r.get('command_id',''))
    if r['kind']=='msg' and r['m']['type'] in ('zone_event','lease_event','drive_rejected'): print(t(r['rx_ms']), json.dumps(r['m'])[:200])
    if r['kind']=='msg' and r['m']['type']=='hello': print(t(r['rx_ms']),'hello zones',[(z['zone_id'],z['status']) for z in r['m']['zones'] if z['status']!='OPEN'])
print('== every sent line and every ack, in order ==')
for r in rows:
    if r['kind']=='sent' and '"drive"' not in r['raw']: print(t(r['rx_ms']),'SENT',r['raw'][:150])
    if r['kind']=='msg' and r['m']['type']=='command_ack': m=r['m']; print(t(r['rx_ms']),'ACK ',m['command_id'],m['vehicle_id'],m['status'],m.get('reason',''))
EOF

