import json, collections
def num(x): return float(x) if isinstance(x,(int,float)) and not isinstance(x,bool) else (float(x) if isinstance(x,str) and x.replace('.','',1).isdigit() else None)
for name in ('capture.jsonl','run2.jsonl','run3.jsonl'):
    rows=[json.loads(l) for l in open(name)]
    route=[r['m'] for r in rows if r['kind']=='msg' and r['m']['type']=='hello'][0]['route']; start={s['segment_id']:s['start_m'] for s in route}
    def pos(m):
        o=num(m.get('offset_m')); return start[m['segment_id']]+o if o is not None and m.get('segment_id') in start else None
    hb=[r['rx_ms'] for r in rows if r['kind']=='msg' and r['m']['type']=='heartbeat']
    tel=collections.defaultdict(list)
    for r in rows:
        if r['kind']=='msg' and r['m']['type']=='telemetry': tel[r['m']['vehicle_id']].append((r['rx_ms'],r['m']))
    out=[]
    for v,l in sorted(tel.items()):
        # frozen episodes at threshold 3 s, in arrival order keeping the max-seq message (simulates ingest)
        best=None; run=None; eps=[]
        for rx,m in l:
            if best and isinstance(m['seq'],int) and m['seq']<=best['seq'] and m['seq']>best['seq']-50: continue
            best=m; p=pos(m); sp=num(m.get('speed_mps')) or 0; st=str(m.get('state')).upper()
            moving_claim = st in ('TRAMMING','MANUAL') and sp>=0.5
            if moving_claim and p is not None:
                if run and abs(p-run[1])<0.05:
                    if rx-run[0]>=3000 and not run[2]: eps.append(rx); run[2]=True
                else: run=[rx,p,False]
            else: run=None
        # silences > 5 s not explained by whole-link silence
        gaps=[(a,b) for (a,_),(b,_) in zip(l,l[1:]) if b-a>5000]
        linkgaps=[(a,b) for a,b in zip(hb,hb[1:]) if b-a>3000]
        own=[(a,b) for a,b in gaps if not any(la-3000<=a<=lb for la,lb in linkgaps)]
        normal=sorted(b-a for (a,_),(b,_) in zip(l,l[1:]) if b-a<=5000)
        out.append((v,len(eps),len(own),normal[int(len(normal)*0.999)] if normal else 0, normal[-1] if normal else 0))
    print(name)
    for v,e,g,p999,mx in out: print('  %s frozen-episodes@3s=%d own-silences>5s=%d  normal gap p99.9=%dms max=%dms'%(v,e,g,p999,mx))
EOF

