                who = 'Agent' if r['type'] == 'assistant' else 'Prompt'
                out += ['### %s (%s)' % (who, stamp), '', c['text'], '']
            elif kind == 'thinking' and c.get('thinking', '').strip():
                out += ['<details><summary>Thinking</summary>', '', c['thinking'], '', '</details>', '']
