cd /private/tmp/claude-501/-Volumes-Transcend-control-room/32fe60a1-e041-40fe-8193-6f7f1a82a633/scratchpad && E=$(grep -o '^GATEWAY_EMAIL=.*' /Volumes/Transcend/control_room/.env | cut -d= -f2); echo "email in reprobe log: $(grep -cF "$E" reprobe1.jsonl)"; python3 - <<'EOF'
import json
rows=[json.loads(l) for l in open('reprobe1.jsonl')]
route=[r['m'] for r in rows if r['kind']=='msg' and r['m']['type']=='hello'][0]['route']; start={s['segment_id']:s['start_m'] for s in route}
def pos(m):
    try: return start[m['segment_id']]+float(m['offset_m'])
    except: return None
def tel(v,a,b):
    out=[]; best=None
    for r in rows:
        if r['kind']=='msg' and r['m']['type']=='telemetry' and r['m']['vehicle_id']==v and a<=r['rx_ms']<=b:
            m=r['m']
            if best is None or m['seq']>best: best=m['seq']; out.append((r['rx_ms'],m))
    return out
sent={json.loads(r['raw'])['command_id']:(r['rx_ms'],json.loads(r['raw'])) for r in rows if r['kind']=='sent' and '"command"' in r['raw']}
for cid,(t,c) in sorted(sent.items(), key=lambda x:x[1][0]): print(cid, c['vehicle_id'], c['action'], t)
def trace(v, t0, secs, label):
    print('==',label)
    last=None
    for rx,m in tel(v,t0-2000,t0+secs*1000):
        k=(m['state'],m['task'],m['direction'],m['speed_mps'],m['zone_id'],m['payload_kg'])
        if k!=last: print('  %+7.2fs seq %s %s pos %.2f'%((rx-t0)/1000,m['seq'],k,pos(m) or -1)); last=k
