import json, collections
for name in ('capture.jsonl','run2.jsonl','run3.jsonl'):
    rows=[json.loads(l) for l in open(name)]
    msgs=[r['rx_ms'] for r in rows if r['kind'] in ('msg','unparseable')]
    outs=[(a,b) for a,b in zip(msgs,msgs[1:]) if b-a>3000]  # whole-link silence, tight edges
    tel=collections.defaultdict(list)
    for r in rows:
        if r['kind']=='msg' and r['m']['type']=='telemetry': tel[r['m']['vehicle_id']].append((r['rx_ms'],r['m']['seq'],r['m']['t_device_ms']))
    res={}
    for method in ('heartbeat-gaps(mine)','tight'):
        if method.startswith('heart'):
            hb=[r['rx_ms'] for r in rows if r['kind']=='msg' and r['m']['type']=='heartbeat']
            o=[(a,b) for a,b in zip(hb,hb[1:]) if b-a>3000]
        else: o=outs
        loss=exp=0
        for v,l in tel.items():
            epochs=[[]]; mx=None
            for rx,s,td in l:
                if mx is not None and s<mx-200: epochs.append([]); mx=None
                epochs[-1].append((rx,s,td)); mx=s if mx is None else max(mx,s)
            for e in epochs:
                seqs={s for _,s,_ in e}; lo,hi=min(seqs),max(seqs)
                # seqs the truck sent while the link was out: by device time inside the outage window, at 5 Hz
                out_s=sum((b-a) for a,b in o if e[0][0]<=a<=e[-1][0])/200
                exp+=hi-lo+1-out_s; loss+=max(0,hi-lo+1-out_s-len(seqs))
        res[method]=round(100*loss/exp,2)
    print(name, 'outages', [round((b-a)/1000,1) for a,b in outs], res)
EOF

