// Draw every frame of video.html in headless Chrome. Usage: node capture.mjs [fps] [only-times...]
import { chromium } from '/Volumes/Transcend/control_room/node_modules/playwright-core/index.mjs';
import { mkdirSync } from 'node:fs';

const here = new URL('.', import.meta.url).pathname;
const fps = Number(process.argv[2] ?? 30);
const stills = process.argv.slice(3).map(Number);
const browser = await chromium.launch({ channel: 'chrome' });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 });
await page.goto('file://' + here + 'video.html');
await page.evaluate(() => window.ready);

if (stills.length) {
  mkdirSync(here + 'stills', { recursive: true });
  for (const t of stills) {
    await page.evaluate((t) => window.render(t), t);
    await page.screenshot({ path: `${here}stills/t${t.toFixed(2)}.png` });
  }
} else {
  mkdirSync(here + 'frames', { recursive: true });
  const n = Math.round(21.0 * fps);
  for (let i = 0; i < n; i++) {
    await page.evaluate((t) => window.render(t), i / fps);
    await page.screenshot({ path: `${here}frames/f${String(i).padStart(4, '0')}.jpg`, type: 'jpeg', quality: 93 });
  }
  console.log('frames', n);
}
await browser.close();

