    this.#unsub.push(() => this.#alerting.stop());
    this.#unsub.push(this.attention.subscribe((e) => this.#attentionEvent(e)));
    this.#unsub.push(o.registry.subscribe((e) => this.#registryEvent(e)));
    if (o.blast) {
