// Walkthrough screenshots during the 15-minute soak, from the hosted instance. Reads the password from
// SOAK_PW (never printed). Usage: SOAK_PW=... node soak-shots.mjs OUTDIR MINUTES
import { chromium } from '/Volumes/Transcend/control_room/node_modules/playwright-core/index.mjs';
import { mkdirSync, writeFileSync } from 'node:fs';

const BASE = 'https://dlh.150-136-98-129.sslip.io';
const out = process.argv[2]; const minutes = Number(process.argv[3] ?? 15);
mkdirSync(out, { recursive: true });
const log = [];
const note = (s) => { const line = `${new Date().toISOString()} ${s}`; log.push(line); console.log(line); };

const browser = await chromium.launch({ channel: 'chrome' });
const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
await page.goto(BASE + '/login');
await page.fill('input[name=username]', 'priya');
await page.fill('input[name=password]', process.env.SOAK_PW ?? '');
