await page.waitForSelector('#rows tr', { timeout: 30_000 });
note('logged in as priya');

const shot = async (name, sel) => {
  const path = `${out}/${name}`;
  if (sel) { const el = await page.$(sel); if (el) await el.screenshot({ path }); else return; }
  else await page.screenshot({ path, fullPage: true });
  note(`shot ${name}`);
};

const end = Date.now() + minutes * 60_000;
let tookClosing = false, tookClosed = false, tookDetail = false, tookTray = false, n = 0;
await page.waitForTimeout(20_000);
await shot('01-overview-start.png');
while (Date.now() < end) {
  const zones = await page.$$eval('main section.clearance [data-verdict]', (rs) => rs.map((r) => r.textContent ?? ''));
