  if (zones.length && !tookClosing) { await shot('02-zone-closing-overview.png'); await shot('03-clearance-panel.png', 'main section.clearance'); tookClosing = true; }
  if (anyClosed && !tookClosed) { await shot('04-zone-closed-overview.png'); tookClosed = true; }
  if (!tookTray && await page.$('#tray-interrupts .item')) { await shot('05-attention-tray.png', '#tray'); tookTray = true; }
  if (!tookDetail && Date.now() > end - minutes * 60_000 + 6 * 60_000) {
    const row = await page.$('#rows tr[data-truck]');
    if (row) { await row.click(); await page.waitForTimeout(2_000); await shot('06-truck-detail.png', '#detail'); await page.click('#detail-close').catch(() => {}); tookDetail = true; }
  }
  if (++n % 36 === 0) await shot(`07-overview-${String(n / 36).padStart(2, '0')}.png`); // about every 3 minutes
  await page.waitForTimeout(5_000);
}
await shot('08-overview-end.png');
await browser.close();
writeFileSync(`${out}/shots.log`, log.join('\n') + '\n');

